export type AnalysisMessageKey = (typeof rows)[number][0]

const localeOrder = ['en', 'ar', 'es', 'fr', 'ja', 'ko', 'vi', 'zh-Hans', 'zh-Hant', 'de', 'ru'] as const satisfies readonly Locale[]

export const analysisCatalogs = Object.fromEntries(localeOrder.map((locale, localeIndex) => [
  locale,
  Object.fromEntries(rows.map(([key, translations]) => [key, translations[localeIndex]])),
])) as Record<Locale, Record<AnalysisMessageKey, string>>
